1	import type { HourCell } from "@/lib/generator/types";
2	import { roundCoord } from "@/lib/weather/location";
3	
4	export const RAIN_CODES = new Set([51, 53, 55, 61, 63, 65, 80, 81, 82, 95, 96, 99]);
5	
6	type Raw = {
7	  timezone: string;
8	  current: {
9	    time: string;
10	    temperature_2m: number;
11	    apparent_temperature: number;
12	    weather_code: number;
13	  };
14	  hourly: {
15	    time: string[];
16	    temperature_2m: number[];
17	    weather_code: number[];
18	    precipitation_probability: number[];
19	  };
20	  /**
21	   * Today's range. Optional so older fixtures and any cached response without it
22	   * still map — callers fall back to the current temperature, which is the
23	   * behaviour that shipped before.
24	   */
25	  daily?: { temperature_2m_max?: number[]; temperature_2m_min?: number[] };
26	};
27	
28	function conditionFor(code: number): string {
29	  if (RAIN_CODES.has(code)) return "Rain";
30	  if (code === 0) return "Clear";
31	  if (code <= 2) return "Partly cloudy";
32	  return "Overcast";
33	}
34	
35	/** "2026-01-14T18:00" → "18:00" */
36	function hhmm(iso: string): string {
37	  return (iso.split("T")[1] ?? "").slice(0, 5);
38	}
39	
40	/**
41	 * Pure — never calls the clock. `nowIso` defaults to `raw.current.time`, which is
42	 * local time AT THE LOCATION (because we send timezone=auto) and therefore on the
43	 * same clock as `raw.hourly.time`. Callers may still inject a now for tests.
44	 */
45	export function mapForecast(
46	  raw: Raw,
47	  nowIso: string = raw.current.time,
48	): {
49	  tempC: number;
50	  feelsLikeC: number;
51	  condition: string;
52	  timezone: string;
53	  hourly: HourCell[];
54	  highC: number;
55	  lowC: number;
56	} {
57	  const times = raw.hourly.time;
58	  let nowIdx = times.findIndex((t) => t >= nowIso); // first hour at/after now
59	  if (nowIdx < 0) nowIdx = 0;
60	
61	  const hourly: HourCell[] = [];
62	  for (let k = 0; k < 4 && nowIdx + k < times.length; k++) {
63	    const i = nowIdx + k;
64	    hourly.push({
65	      hh: hhmm(times[i]),
66	      tempC: Math.round(raw.hourly.temperature_2m[i]),
67	      rain: RAIN_CODES.has(raw.hourly.weather_code[i]),
68	      isNow: k === 0,
69	    });
70	  }
71	
72	  // The look is built for the day's HIGH, not for the minute the app was
73	  // opened — the daily drop is generated once and worn all day. Falls back to
74	  // the current temperature when the API response carries no daily block, which
75	  // is exactly the behaviour that shipped before.
76	  const now = Math.round(raw.current.temperature_2m);
77	  const max = raw.daily?.temperature_2m_max?.[0];
78	  const min = raw.daily?.temperature_2m_min?.[0];
79	
80	  return {
81	    tempC: now,
82	    feelsLikeC: Math.round(raw.current.apparent_temperature),
83	    condition: conditionFor(raw.current.weather_code),
84	    timezone: raw.timezone,
